var n=`1078-pancit-canton`;var t=`world-1078`;var a=`PH`;var s=`southeast-asia`;var o=4;var r=27;var g={en:`Pancit Canton`,ua:`Пансіт кантон`};var l={en:`Pancit Canton is a dish from Philippines prepared with chow mein noodles, garlic, yellow onion, chicken breast. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Пансіт кантон, страва кухні країни Філіппіни, яку готують із таких продуктів: локшина чоу-мейн, часник, жовта цибуля, куряча грудка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Cook the listed ingredients in simmering water for about 7 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 7 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:7,i:[[`chow-mein-noodles`,450,`g`],[`water`,1e3,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`garlic`,4,`clove`],[`yellow-onion`,170,`g`],[`chicken-breast`,350,`g`],[`shrimp`,250,`g`],[`canola-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 7 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 7 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:7,i:[[`white-cabbage`,200,`g`],[`carrot`,160,`g`],[`green-beans`,160,`g`],[`light-soy-sauce`,45,`ml`],[`oyster-sauce`,35,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,35,`g`]]}];var h={slug:n,id:t,country:`PH`,region:s,servings:4,minutes:27,title:g,text:l,steps:d};export{a as country,h as default,t as id,r as minutes,s as region,o as servings,n as slug,d as steps,l as text,g as title};